window.HOEREN_TESTS[12] = {"id":"verkehr-und-stadt","name":"Verkehr und Stadt","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Achtung an die Fahrgäste der U-Bahn-Linie 4. Wegen Bauarbeiten zwischen Hauptbahnhof und Rathaus fahren wir heute nur bis Hauptbahnhof. Ein Ersatz-Bus fährt von dort zum Rathaus, alle 10 Minuten. Bitte warten Sie nicht, nehmen Sie den Bus. Die Linie 7 fährt normal — Sie können auch dort umsteigen. Vielen Dank!","gender":"f","q":"Wie kommen Fahrgäste vom Hauptbahnhof zum Rathaus?","opts":["Mit der U-Bahn-Linie 4.","Sie müssen warten.","Mit dem Ersatz-Bus."],"correct":2},{"transcript":"Hier ist der Verkehrsfunk. Auf der Stadtautobahn Richtung Süden gibt es einen schweren Unfall. Mindestens 30 Minuten Wartezeit. Wir empfehlen, über die Bahnhofstraße oder die Münchner Straße auszuweichen. Auch die Linie 8 der Straßenbahn fährt normal — kein Stau für die. Der Stau dauert noch lange, fahren Sie vorsichtig. Gute Fahrt!","gender":"m","q":"Was sollen Autofahrer machen?","opts":["Auf der Autobahn bleiben.","Mit der Straßenbahn fahren.","Auf Bahnhofstraße oder Münchner Straße ausweichen."],"correct":2},{"transcript":"Liebe Fahrgäste, der Bus 47 fällt heute ganz aus, wegen Wartungsarbeiten. Bitte nutzen Sie statt 47 die Linie 23 — die hält direkt nebenan und fährt fast die gleiche Strecke. Nicht Linie 8 und nicht Linie 7, sondern Linie 23. Morgen läuft die Linie 47 wieder normal. Wir entschuldigen uns für die Unannehmlichkeiten. Danke!","gender":"f","q":"Welcher Bus ersetzt die Linie 47?","opts":["Die Linie 23.","Die Linie 8.","Die Linie 7."],"correct":0},{"transcript":"Hallo Schatz, hier ist Papa. Ich stehe gerade in einem riesigen Stau. Ich werde noch eine Stunde brauchen, um nach Hause zu kommen. Bitte iss schon ohne mich, und kümmere dich um den Hund — er muss spätestens um 19 Uhr raus. Ich komme so schnell ich kann.","gender":"m","q":"Was soll die Familie tun?","opts":["Ohne Papa essen, sich um den Hund kümmern.","Auf Papa warten zum Essen.","Den Hund zu Papa bringen."],"correct":0},{"transcript":"Sehr geehrte Reisende, die Fähre von Helgoland zurück nach Cuxhaven fährt heute zwei Stunden später als geplant. Statt um 14 Uhr starten wir erst um 16 Uhr. Grund ist starker Wellengang am Morgen. Wer dringend zurück muss, kann den Schnellzug-Tunnel-Service nehmen — der ist allerdings teurer.","gender":"f","q":"Wann startet die Fähre?","opts":["Um 14 Uhr.","Um 16 Uhr.","Sie fährt gar nicht."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer kommt wie? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Anna","gender":"f","text":"Hallo Markus! Das Fest in Hamburg ist am Samstag. Wir müssen die Anreise heute klären."},{"speaker":"Markus","gender":"m","text":"Ich habe die ganze Gruppe gefragt. Die Wege sind bei allen ganz unterschiedlich."},{"speaker":"Anna","gender":"f","text":"Ich komme mit dem Zug um elf am Hauptbahnhof an. Die Fahrkarte ist schon gebucht."},{"speaker":"Markus","gender":"m","text":"Am Bahnhof hole ich dich nicht ab. Ich komme mit dem Auto und nehme andere mit."},{"speaker":"Anna","gender":"f","text":"Im Auto ist Platz für zwei Personen. Nimmt jemand aus der Gruppe ein Taxi?"},{"speaker":"Markus","gender":"m","text":"Nein. Ein Taxi nehmen wir nicht. Das wird für die kurze Strecke zu teuer."},{"speaker":"Anna","gender":"f","text":"Sara wohnt viel weiter weg. Sie ist mit dem Auto zu lange unterwegs."},{"speaker":"Markus","gender":"m","text":"Sara fliegt mit dem Flugzeug. Sie landet schon am Freitagabend in Hamburg."},{"speaker":"Anna","gender":"f","text":"Das Flugzeug ist teuer aber schnell. Lukas hat dieses Mal nur wenig Geld."},{"speaker":"Markus","gender":"m","text":"Lukas kommt mit dem Fernbus in der Nacht an. Die Fahrt dauert wirklich lange."},{"speaker":"Anna","gender":"f","text":"Der Fernbus hält direkt am Busbahnhof. Tim hat ein Motorrad. Kommt er damit über die Landstraße?"},{"speaker":"Markus","gender":"m","text":"Mit dem Motorrad kommt kein Gast. Die Straße ist bei Regen zu gefährlich."},{"speaker":"Anna","gender":"f","text":"Tom und Lisa wohnen ja hier in der Stadt. Zu Fuß ist bei dem Wetter angenehm."},{"speaker":"Markus","gender":"m","text":"Tom und Lisa gehen zu Fuß. Vom Bahnhof sind es nur zehn Minuten."},{"speaker":"Anna","gender":"f","text":"Einverstanden. Ich schreibe die Ankunftszeiten in die Gruppe. Bis Samstag am Fest."}],"options":[{"letter":"a","text":"geht zu Fuß"},{"letter":"b","text":"kommt mit dem Auto und nimmt andere mit"},{"letter":"c","text":"kommt mit dem Taxi"},{"letter":"d","text":"kommt mit dem Fernbus"},{"letter":"e","text":"fährt mit dem Fahrrad"},{"letter":"f","text":"kommt mit der Fähre"},{"letter":"g","text":"kommt mit dem Zug"},{"letter":"h","text":"fliegt mit dem Flugzeug"},{"letter":"i","text":"fährt mit dem Motorrad"}],"items":[{"person":"Anna","correct":"g"},{"person":"Markus","correct":"b"},{"person":"Sara","correct":"h"},{"person":"Lukas","correct":"d"},{"person":"Tom und Lisa","correct":"a"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Tourist","gender":"m","text":"Entschuldigung, wie komme ich zum Schloss?"},{"speaker":"Einheimischer","gender":"m","text":"Mit dem Bus 8 — er fährt direkt hin. Kein Taxi nötig."},{"speaker":"Tourist","gender":"m","text":"Wie lange dauert es?"},{"speaker":"Einheimischer","gender":"m","text":"Etwa 15 Minuten. Oder zu Fuß 35 Minuten, der Weg ist schön."},{"speaker":"Tourist","gender":"m","text":"Es regnet bald, ich nehme den Bus. Danke!"},{"speaker":"Einheimischer","gender":"m","text":"Gute Fahrt! Der Bus kommt in fünf Minuten!"}],"q":"Wie geht der Tourist zum Schloss?","opts":["Mit dem Bus.","Zu Fuß.","Mit dem Taxi."],"correct":0},{"lines":[{"speaker":"Taxifahrerin","gender":"f","text":"Wohin möchten Sie?"},{"speaker":"Fahrgast","gender":"m","text":"Zum Hauptbahnhof, bitte."},{"speaker":"Taxifahrerin","gender":"f","text":"Über die Stadtmitte oder die Umgehungsstraße? Der kürzeste Weg ist Mitte, aber mit Stau. Umgehung 5 Minuten länger aber sicher schneller."},{"speaker":"Fahrgast","gender":"m","text":"Umgehung. Ich muss meinen Zug erreichen."},{"speaker":"Taxifahrerin","gender":"f","text":"Gut, dann sind wir in 12 Minuten dort. Kein Stau heute!"},{"speaker":"Fahrgast","gender":"m","text":"Perfekt! 12 Minuten reicht für meinen Zug. Danke!"}],"q":"Welche Strecke fährt das Taxi?","opts":["Über die Umgehungsstraße.","Über die Stadtmitte.","Den kürzesten Weg."],"correct":0},{"lines":[{"speaker":"Schalterbeamte","gender":"m","text":"Eine Fahrkarte wohin?"},{"speaker":"Reisende","gender":"f","text":"Eine Tageskarte für die Stadt, bitte. Für heute und morgen?"},{"speaker":"Schalterbeamte","gender":"m","text":"Erwachsenenkarte 8 Euro, mit Studentenausweis 5 Euro. Familienkarte 12."},{"speaker":"Reisende","gender":"f","text":"Ich bin Studentin, hier ist mein Ausweis. Eine Karte, bitte."},{"speaker":"Schalterbeamte","gender":"m","text":"Das macht 5 Euro. Hier ist Ihre Karte! Bitteschön!"},{"speaker":"Reisende","gender":"f","text":"Danke! 5 Euro für den ganzen Tag, super! Bis morgen!"}],"q":"Wie viel zahlt die Studentin?","opts":["8 Euro.","5 Euro.","12 Euro."],"correct":1},{"lines":[{"speaker":"Mann","gender":"m","text":"Mein Auto wurde gestohlen!"},{"speaker":"Polizist","gender":"m","text":"Wo stand es?"},{"speaker":"Mann","gender":"m","text":"Auf dem Marktplatz, vor dem Rathaus. Eigentlich verboten dort, aber kurz."},{"speaker":"Polizist","gender":"m","text":"Wann haben Sie es zuletzt gesehen?"},{"speaker":"Mann","gender":"m","text":"Heute Morgen um 9 Uhr, nicht gestern Abend. Jetzt ist es 13 Uhr, vier Stunden weg."},{"speaker":"Polizist","gender":"m","text":"Verstanden! Wir suchen sofort. Haben Sie ein Foto vom Auto?"}],"q":"Wann hat der Mann sein Auto zuletzt gesehen?","opts":["Gestern Abend.","Um 13 Uhr.","Um 9 Uhr morgens."],"correct":2},{"lines":[{"speaker":"Junge","gender":"m","text":"Mama, wir kommen zu spät zum Kino!"},{"speaker":"Mutter","gender":"f","text":"Beruhig dich. Wir nehmen ein Taxi statt der Straßenbahn, kein Problem."},{"speaker":"Junge","gender":"m","text":"Taxi ist teurer. Zu Fuß schaffen wir es nicht mehr."},{"speaker":"Mutter","gender":"f","text":"Nur 8 Euro mehr. Los, wir schaffen den Film!"},{"speaker":"Junge","gender":"m","text":"Okay, dann Taxi! Aber beeilen wir uns!"},{"speaker":"Mutter","gender":"f","text":"Ja, los! In zehn Minuten sind wir da!"}],"q":"Wie fahren sie zum Kino?","opts":["Mit der Straßenbahn.","Sie gehen zu Fuß.","Mit dem Taxi."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Friedrich, einem Busfahrer. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Herr Friedrich, Sie sind Busfahrer seit über 20 Jahren. Wie sind Sie zu diesem Beruf gekommen?"},{"speaker":"Friedrich","gender":"m","text":"Mein Großvater war Straßenbahnführer. Schon als kleiner Junge habe ich immer die Busse gemocht. Ich wollte zuerst Lokführer werden, aber die Ausbildung war nichts für mich. So habe ich Busfahrer gewählt — das passt mir besser, weil ich die ganze Stadt sehe."},{"speaker":"Reporter","gender":"m","text":"Wie sind Ihre Arbeitszeiten?"},{"speaker":"Friedrich","gender":"m","text":"Unregelmäßig. Manche Wochen Frühschicht — ab 4 Uhr morgens. Manche Wochen Spätschicht bis Mitternacht. Wir haben kein Wochenende — Samstag und Sonntag fahren auch Busse. Aber dafür zweimal pro Monat ein freier Mittwoch."},{"speaker":"Reporter","gender":"m","text":"Wie viele Fahrgäste an einem normalen Tag?"},{"speaker":"Friedrich","gender":"m","text":"Zwischen 500 und 1000, je nach Linie und Wetter. Bei Regen sind es mehr — viele lassen ihr Fahrrad zu Hause. Bei Schnee dauert die Fahrt länger, aber Fahrgäste sind dann oft entspannter."},{"speaker":"Reporter","gender":"m","text":"Gibt es schwierige Fahrgäste?"},{"speaker":"Friedrich","gender":"m","text":"Selten, ehrlich gesagt. Vielleicht einmal pro Woche. Meistens sind die Leute freundlich. Ich grüße jeden — das hilft sehr. Probleme gibt es eher mit anderen Autofahrern, die unhöflich fahren."},{"speaker":"Reporter","gender":"m","text":"Was machen Sie in Ihrer Freizeit?"},{"speaker":"Friedrich","gender":"m","text":"Ich fahre Fahrrad! Stundenlang im Wald, weg von der Stadt. Auch ein Auto besitze ich nicht — was ich täglich beruflich fahre, brauche ich privat nicht. Lesen mag ich auch."}],"items":[{"q":"Er hat jedes Wochenende frei.","correct":"nein"},{"q":"Herr Friedrich wollte ursprünglich Lokführer werden.","correct":"ja"},{"q":"Bei Regen fahren weniger Leute im Bus.","correct":"nein"},{"q":"Schwierige Fahrgäste sind sehr häufig.","correct":"nein"},{"q":"In seiner Freizeit fährt er gern Auto.","correct":"nein"}]}]};
